    double totalThicknessIU = 0.0;
    double weightedDk = 0.0;

    for( int i = aSignalIdx + aDirection; i >= 0 && i < (int) aLayers.size(); i += aDirection )
    {
        BOARD_STACKUP_ITEM* item = aLayers[i];

        if( !item || !item->IsEnabled() )
            continue;

        if( item->GetType() == BS_ITEM_TYPE_COPPER )
            break;

        if( item->GetType() != BS_ITEM_TYPE_DIELECTRIC )
            continue;

        const int t = item->GetThickness();

        if( t <= 0 )
            continue;

        totalThicknessIU += t;
        weightedDk += t * item->GetEpsilonR();
    }

    if( totalThicknessIU <= 0 )
        return { 0.0, 0.0 };

    // Convert IU (nanometres) → metres
    const double heightM = totalThicknessIU / 1e9;
    const double dk      = weightedDk / totalThicknessIU;

    return { heightM, dk };
}


static int findStackupCopperIndex( const std::vector<BOARD_STACKUP_ITEM*>& aLayers,
                                   PCB_LAYER_ID aLayer )
{
    for( size_t i = 0; i < aLayers.size(); ++i )
    {
        BOARD_STACKUP_ITEM* item = aLayers[i];

        if( item && item->IsEnabled() && item->GetType() == BS_ITEM_TYPE_COPPER
            && item->GetBrdLayerId() == aLayer )
        {
            return static_cast<int>( i );
        }
    }

    return -1;
}


int DRC_TEST_PROVIDER_IMPEDANCE::computeImpedance( BOARD* aBoard, const BOARD_STACKUP& aStackup,
                                                   PCB_LAYER_ID aLayer, int aWidthIU )
{
    CACHE_KEY key{ aLayer, aWidthIU };
    auto      it = m_cache.find( key );

    if( it != m_cache.end() )
        return it->second;

    const std::vector<BOARD_STACKUP_ITEM*>& layers = aStackup.GetList();
    const int                                signalIdx = findStackupCopperIndex( layers, aLayer );

    if( signalIdx < 0 || aWidthIU <= 0 )
    {
        m_cache[key] = 0;
        return 0;
    }

    BOARD_STACKUP_ITEM* signal = layers[signalIdx];
    const double        signalThicknessM = signal->GetThickness() / 1e9;
    const double        widthM           = aWidthIU / 1e9;

    // Outer layers (F.Cu, B.Cu) → microstrip; inner copper layers → stripline.
    const bool isOuter = ( aLayer == F_Cu || aLayer == B_Cu );

    double z0 = 0.0;

    if( isOuter )
    {
        auto [heightM, dk] = collectDielectricToReference( layers, signalIdx,
                                                           ( aLayer == F_Cu ) ? +1 : -1 );

        if( heightM <= 0.0 || dk <= 0.0 )
        {
            m_cache[key] = 0;
            return 0;
        }

        MICROSTRIP ms;
        ms.SetParameter( TRANSLINE_PARAMETERS::PHYS_WIDTH, widthM );
        ms.SetParameter( TRANSLINE_PARAMETERS::T, signalThicknessM );
        ms.SetParameter( TRANSLINE_PARAMETERS::H, heightM );
        ms.SetParameter( TRANSLINE_PARAMETERS::H_T, 1e6 );  // free air above; effectively infinite
        ms.SetParameter( TRANSLINE_PARAMETERS::EPSILONR, dk );
        ms.SetParameter( TRANSLINE_PARAMETERS::MUR, 1.0 );
        ms.SetParameter( TRANSLINE_PARAMETERS::MURC, 1.0 );
        ms.SetParameter( TRANSLINE_PARAMETERS::FREQUENCY, 1e9 );
        ms.SetParameter( TRANSLINE_PARAMETERS::TAND, 0.0 );
        ms.SetParameter( TRANSLINE_PARAMETERS::ROUGH, 0.0 );
        ms.SetParameter( TRANSLINE_PARAMETERS::SIGMA, 1.0 / RHO );
        ms.SetParameter( TRANSLINE_PARAMETERS::PHYS_LEN, 1.0 );
        ms.SetParameter( TRANSLINE_PARAMETERS::ANG_L, 1.0 );

        ms.Analyse();

        auto& results = ms.GetAnalysisResults();
        auto  zIt = results.find( TRANSLINE_PARAMETERS::Z0 );

        if( zIt != results.end() && zIt->second.second == TRANSLINE_STATUS::OK )
            z0 = zIt->second.first;
    }
    else
    {
        auto [topH, topDk] = collectDielectricToReference( layers, signalIdx, -1 );
        auto [botH, botDk] = collectDielectricToReference( layers, signalIdx, +1 );

        if( topH <= 0.0 || botH <= 0.0 )
        {
            m_cache[key] = 0;
            return 0;
        }

        // Weighted average for symmetric stripline calculation
        const double totalH = topH + botH;
        const double dk     = ( topH * topDk + botH * botDk ) / totalH;

        STRIPLINE sl;
        sl.SetParameter( TRANSLINE_PARAMETERS::PHYS_WIDTH, widthM );
        sl.SetParameter( TRANSLINE_PARAMETERS::T, signalThicknessM );
        sl.SetParameter( TRANSLINE_PARAMETERS::H, totalH + signalThicknessM );
        sl.SetParameter( TRANSLINE_PARAMETERS::STRIPLINE_A, topH );
        sl.SetParameter( TRANSLINE_PARAMETERS::EPSILONR, dk );
        sl.SetParameter( TRANSLINE_PARAMETERS::MUR, 1.0 );
        sl.SetParameter( TRANSLINE_PARAMETERS::MURC, 1.0 );
        sl.SetParameter( TRANSLINE_PARAMETERS::FREQUENCY, 1e9 );
        sl.SetParameter( TRANSLINE_PARAMETERS::TAND, 0.0 );
        sl.SetParameter( TRANSLINE_PARAMETERS::SIGMA, 1.0 / RHO );
        sl.SetParameter( TRANSLINE_PARAMETERS::PHYS_LEN, 1.0 );
        sl.SetParameter( TRANSLINE_PARAMETERS::ANG_L, 1.0 );

        sl.Analyse();

        auto& results = sl.GetAnalysisResults();
        auto  zIt = results.find( TRANSLINE_PARAMETERS::Z0 );

        if( zIt != results.end() && zIt->second.second == TRANSLINE_STATUS::OK )
            z0 = zIt->second.first;
    }

    // Store as integer ohms (matches the rule parser's integer MIN/OPT/MAX scale).
    const int z0Ohms = static_cast<int>( z0 + 0.5 );
    m_cache[key]     = z0Ohms;
    return z0Ohms;
}


bool DRC_TEST_PROVIDER_IMPEDANCE::Run()
{
    if( m_drcEngine->IsErrorLimitExceeded( DRCE_IMPEDANCE_OUT_OF_RANGE ) )
    {
        REPORT_AUX( wxT( "Impedance violations ignored. Skipping check." ) );
        return true;
    }

    if( !m_drcEngine->HasRulesForConstraintType( IMPEDANCE_TARGET_CONSTRAINT ) )
    {
        REPORT_AUX( wxT( "No impedance target constraints found. Tests not run." ) );
        return true;
    }

    if( !reportPhase( _( "Checking track impedance..." ) ) )
        return false;

    BOARD* board = m_drcEngine->GetBoard();

    if( !board )
        return true;

    const BOARD_STACKUP stackup = board->GetStackupOrDefault();

    // Sanity: at least one dielectric must declare a Dk; otherwise impedance is meaningless.
    bool stackupHasDk = false;

    for( BOARD_STACKUP_ITEM* item : stackup.GetList() )
    {
        if( item && item->IsEnabled() && item->GetType() == BS_ITEM_TYPE_DIELECTRIC
            && item->GetEpsilonR() > 1.0 )
        {
            stackupHasDk = true;
            break;
        }
    }

    if( !stackupHasDk )
    {
        REPORT_AUX( wxT( "Stackup has no dielectric constants; impedance check skipped." ) );
        return true;
    }

    m_cache.clear();

    LSET copperLayers = LSET::AllCuMask( board->GetCopperLayerCount() );

    size_t count = 0;
    size_t ii    = 0;

    forEachGeometryItem( { PCB_TRACE_T, PCB_ARC_T }, copperLayers,
            [&]( BOARD_ITEM* ) -> bool
            {
                count++;
                return true;
            } );

    if( count == 0 )
        return true;

    forEachGeometryItem( { PCB_TRACE_T, PCB_ARC_T }, copperLayers,
            [&]( BOARD_ITEM* item ) -> bool
            {
                if( !reportProgress( ii++, count, 100 ) )
                    return false;

                if( m_drcEngine->IsErrorLimitExceeded( DRCE_IMPEDANCE_OUT_OF_RANGE ) )
                    return false;

                PCB_TRACK* track = dynamic_cast<PCB_TRACK*>( item );

                if( !track )
                    return true;

                DRC_CONSTRAINT constraint = m_drcEngine->EvalRules( IMPEDANCE_TARGET_CONSTRAINT,
                                                                    track, nullptr,
                                                                    track->GetLayer() );

                if( constraint.IsNull() || constraint.GetSeverity() == RPT_SEVERITY_IGNORE )
                    return true;

                const int width = track->GetWidth();
                const int z0    = computeImpedance( board, stackup, track->GetLayer(), width );

                if( z0 <= 0 )
                    return true;  // couldn't compute — silently skip (logged once via cache)

                const auto& mom = constraint.m_Value;

                const bool tooLow  = mom.HasMin() && z0 < mom.Min();
                const bool tooHigh = mom.HasMax() && z0 > mom.Max();

                if( !tooLow && !tooHigh )
                    return true;

                std::shared_ptr<DRC_ITEM> drcItem = DRC_ITEM::Create( DRCE_IMPEDANCE_OUT_OF_RANGE );

                wxString msg;
                const wxString src = constraint.GetName();

                if( tooLow )
                {
                    msg = wxString::Format( _( "(%s impedance %d Ω below minimum %d Ω)" ),
                                            src, z0, mom.Min() );
                }
                else
                {
                    msg = wxString::Format( _( "(%s impedance %d Ω above maximum %d Ω)" ),
                                            src, z0, mom.Max() );
                }

                drcItem->SetErrorMessage( drcItem->GetErrorText() + wxS( " " ) + msg );
                drcItem->SetItems( track );
                drcItem->SetViolatingRule( constraint.GetParentRule() );

                reportViolation( drcItem, track->GetPosition(), track->GetLayer() );

                return true;
            } );

    return !m_drcEngine->IsCancelled();
}


namespace detail
{
    static DRC_REGISTER_TEST_PROVIDER<DRC_TEST_PROVIDER_IMPEDANCE> dummy;
}

