wxString ROUTER_TOOL::buildImpedanceStatus() const
{
    BOARD* brd = board();

    if( !brd || !m_router )
        return wxEmptyString;

    const PCB_LAYER_ID layer = m_iface->GetBoardLayerFromPNSLayer( m_router->GetCurrentLayer() );
    const int          width = m_router->Sizes().TrackWidth();

    if( layer == UNDEFINED_LAYER || width <= 0 || !IsCopperLayer( layer ) )
        return wxEmptyString;

    // Pick a representative item from the current net to evaluate per-net rules.
    // Falls back to no item if PNS hasn't started routing yet — the rule still applies
    // class-wide so we can evaluate against the layer alone.
    BOARD_ITEM* refItem = nullptr;
    std::vector<PNS::NET_HANDLE> nets = m_router->GetCurrentNets();

    if( !nets.empty() && nets[0] )
    {
        if( NETINFO_ITEM* netInfo = brd->FindNet( static_cast<int>( reinterpret_cast<intptr_t>( nets[0] ) ) ) )
            (void) netInfo;  // FindNet by handle is brittle; rely on EvalRules layer-only path
    }

    DRC_ENGINE* drcEngine = brd->GetDesignSettings().m_DRCEngine.get();

    if( !drcEngine )
        return wxEmptyString;

    DRC_CONSTRAINT constraint = drcEngine->EvalRules( IMPEDANCE_TARGET_CONSTRAINT, refItem, nullptr,
                                                      layer );

    // Compute Z₀ even without an impedance rule, so the user can see live impedance numbers
    // when manually tuning a track.  Show "target" only when a rule applies.
    IMPEDANCE_CALCULATOR calc;
    const int            z0 = calc.ComputeOhms( brd, layer, width );

    if( z0 <= 0 )
        return wxEmptyString;

    if( constraint.IsNull() )
        return wxString::Format( wxT( "    Z₀ = %d Ω" ), z0 );

    const MINOPTMAX<int>& mom = constraint.m_Value;

    if( mom.HasMin() && mom.HasMax() )
        return wxString::Format( wxT( "    Z₀ = %d Ω (target %d-%d Ω)" ), z0, mom.Min(), mom.Max() );

    if( mom.HasOpt() )
        return wxString::Format( wxT( "    Z₀ = %d Ω (target %d Ω)" ), z0, mom.Opt() );

    return wxString::Format( wxT( "    Z₀ = %d Ω" ), z0 );
}


void ROUTER_TOOL::setTransitions()
{
    Go( &ROUTER_TOOL::SelectCopperLayerPair,  PCB_ACTIONS::selectLayerPair.MakeEvent() );

